#include <cuda_runtime.h>
#include <fstream>
#include <vector>
#include <chrono>
#define main historical_main
#include "../mis-cuda/main.cu"
#undef main
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<int>load(const char*f){std::ifstream in(f,std::ios::binary|std::ios::ate);size_t z=in.tellg();std::vector<int>a(z/4);in.seekg(0);in.read((char*)a.data(),z);return a;}
template<class T>struct Buf{std::vector<T>h;T*raw;T*ptr;T guard;Buf(std::vector<T>v,T g):h(v.size()+8,g),guard(g){std::copy(v.begin(),v.end(),h.begin()+4);ck(cudaMalloc(&raw,h.size()*sizeof(T)));ptr=raw+4;ck(cudaMemcpy(raw,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>get(){std::vector<T>a(h.size());ck(cudaMemcpy(a.data(),raw,a.size()*sizeof(T),cudaMemcpyDeviceToHost));return a;}bool guards(std::vector<T>&a){for(int j=0;j<4;j++)if(a[j]!=guard||a[a.size()-1-j]!=guard)return false;return true;}};
struct Case{int n,e,reps;Buf<int>*idx;Buf<int>*list;Buf<unsigned char>*status;Buf<unsigned char>*priority;std::vector<int>expected_priority,expected_final;};
int main(){auto f=load(MIS_FIXTURE),o=load(MIS_ORACLE);size_t pos=1,oi=0;std::vector<Case>cases;for(int ci=0;ci<f[0];ci++){Case c;c.n=f[pos++];c.e=f[pos++];c.reps=f[pos++];c.idx=new Buf<int>(std::vector<int>(f.begin()+pos,f.begin()+pos+c.n+1),123456789);pos+=c.n+1;c.list=new Buf<int>(std::vector<int>(f.begin()+pos,f.begin()+pos+c.e),123456789);pos+=c.e;c.status=new Buf<unsigned char>(std::vector<unsigned char>(c.n),165);c.priority=new Buf<unsigned char>(std::vector<unsigned char>(c.n),165);c.expected_priority=std::vector<int>(o.begin()+oi,o.begin()+oi+c.n);oi+=c.n;c.expected_final=std::vector<int>(o.begin()+oi,o.begin()+oi+c.n);oi+=c.n;cases.push_back(c);}for(auto&c:cases){init<<<24,256>>>(c.n,c.e,c.idx->ptr,c.status->ptr);findmins<<<24,256>>>(c.n,c.idx->ptr,c.list->ptr,c.status->ptr);ck(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){auto payload=f;bool ok=true;double total=0;std::vector<double>times;for(auto&c:cases){ck(cudaMemset(c.status->ptr,0,c.n));ck(cudaMemset(c.priority->ptr,0,c.n));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int repeat=0;repeat<c.reps;repeat++){init<<<24,256>>>(c.n,c.e,c.idx->ptr,c.status->ptr);findmins<<<24,256>>>(c.n,c.idx->ptr,c.list->ptr,c.status->ptr);}ck(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/c.reps;total+=elapsed;times.push_back(elapsed);auto final=c.status->get();init<<<24,256>>>(c.n,c.e,c.idx->ptr,c.priority->ptr);ck(cudaDeviceSynchronize());auto priority=c.priority->get();for(auto*b:{c.idx,c.list}){auto a=b->get();ok&=b->guards(a)&&a==b->h;payload.insert(payload.end(),a.begin(),a.end());}ok&=c.status->guards(final)&&c.priority->guards(priority);for(auto a:{final,priority})for(auto v:a)payload.push_back(int(v));for(int i=0;i<c.n;i++)ok&=int(final[i+4])==c.expected_final[i]&&int(priority[i+4])==c.expected_priority[i];for(int v=0;v<c.n;v++){bool neighbor=false;for(int j=c.idx->h[v+4];j<c.idx->h[v+5];j++){int nb=c.list->h[j+4];if(final[nb+4]==in)neighbor=true;if(final[v+4]==in)ok&=final[nb+4]!=in;}if(final[v+4]==out)ok&=neighbor;else ok&=final[v+4]==in;}}
std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream file(path,std::ios::binary);file.write((char*)payload.data(),payload.size()*4);file.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%s,\"timing_region\":\"sum7_init_asyncMIS_3repeat_means_complete\",\"jit_excluded\":true,\"internal_repeats\":3,\"timed_kernel_calls\":42,\"priority_capture\":\"deterministic_untimed_init_replay_after_actualtimedfinal_capture\",\"case_times_seconds\":[",trial,total,ok?"true":"false",payload.size(),ok?"0":"null");for(size_t j=0;j<times.size();j++)printf("%s%.17g",j?",":"",times[j]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}}
